// Hợp nhất phát hiện bằng LUẬT, không bằng model — và FAIL CLOSED.
//
// Một lượt thẩm định chỉ HOÀN TẤT khi thoát mã 0, có khối fleet-status và
// `outcome` là success hoặc partial: cùng định nghĩa với policies.turn_problem()
// của LangGraph. run-role.sh tách khối fleet-status CUỐI CÙNG vào `status`.
// Lượt lỗi (runner 504/429/502, thoát mã ≠ 0, thiếu khối, blocked/rejected,
// nhãn lạ) cũng cho ra 0 phát hiện. Nếu không kiểm ở đây, nó trông y hệt một PR
// sạch. Không hoàn tất ≠ sạch: trạng thái khi đó là `error`, hoặc `failure` nếu
// đã có mục chặn. KHÔNG BAO GIỜ là `success`.
//
// Đọc kết quả theo TÊN NODE, không theo thứ tự item: item lỗi của node HTTP
// (onError = tiếp tục) không mang `role`, và vai trò vắng mặt cũng phải bị tính
// là không hoàn tất. Đổi tên node thẩm định thì sửa cả bảng REVIEWS.
//
// Quy tắc "bằng chứng hoặc im lặng": BLOCKER/CRITICAL không có file:dòng bị loại.
// scripts/check-review-gate.mjs chạy chính đoạn code này với các payload mẫu.
const REVIEWS = [
  { node: 'Thẩm định · Codex', role: 'reviewer' },
  { node: 'Thẩm định · Bảo mật', role: 'security' },
  { node: 'Thẩm định · Kiểm thử', role: 'analyst' },
];
const OUTCOMES = ['success', 'partial', 'blocked', 'rejected'];
const RE = /\[?(BLOCKER|CRITICAL|MAJOR|MINOR|NIT)\]?\s*([\w./-]+:\d+)?\s*[|:-]?\s*(.+)/i;
const RANK = { CRITICAL: 5, BLOCKER: 4, MAJOR: 3, MINOR: 2, NIT: 1 };

const oneLine = (v, max) => String(v ?? '').replace(/\s+/g, ' ').trim().slice(0, max);
const cell = (v, max) => oneLine(v, max).replace(/\|/g, '\\|');

// Lỗi HTTP: n8n cho `status` và message dạng '504 - "<thân đã escape>"' (riêng 429 thì
// message bị thay bằng lời khuyên của n8n). Chỉ lấy trường `error` của agent-runner:
// thân 502 có thể kèm stderr của run-role.sh, không được đưa lên PR.
function errorReason(e) {
  const o = e && typeof e === 'object' ? e : { message: e };
  const msg = String(o.message ?? '');
  const m = /^(\d{3}) - "(.*)"$/s.exec(msg);
  const code = o.status || (m && m[1]);
  if (!code) return `không gọi được agent-runner: ${oneLine(msg || o.name || 'không rõ lỗi', 100)}`;
  let why = '';
  if (m) { try { why = JSON.parse(JSON.parse(`"${m[2]}"`)).error || ''; } catch (_) { /* thân không phải JSON */ } }
  return `agent-runner trả HTTP ${code}${why ? `: ${oneLine(why, 100)}` : ''}`;
}

// Lý do lượt KHÔNG hoàn tất; chuỗi rỗng = hoàn tất.
function turnProblem(p, role) {
  if ('error' in p) return errorReason(p.error);
  if (p.exit !== 0) return typeof p.exit === 'number' ? `thoát mã ${p.exit}` : 'không có mã thoát';
  if (p.role !== role) return `vai trò trả về là '${oneLine(p.role, 30)}', không phải '${role}'`;
  const st = p.status;
  if (!st || typeof st !== 'object' || Array.isArray(st) || !Object.keys(st).length) {
    return 'thiếu khối fleet-status';
  }
  if (!Object.prototype.hasOwnProperty.call(st, 'outcome')) return 'khối fleet-status thiếu outcome';
  const outcome = String(st.outcome).trim().replace(/^[`'".]+|[`'".]+$/g, '').toLowerCase();
  if (!OUTCOMES.includes(outcome)) return `outcome không hợp lệ: '${outcome.slice(0, 40)}'`;
  if (outcome === 'blocked' || outcome === 'rejected') return `outcome: ${outcome}`;
  return '';
}

const runs = [];
const byKey = new Map();
for (const { node, role } of REVIEWS) {
  let items = [];
  try { items = $(node).all(); } catch (e) { /* node không chạy, hoặc đã bị đổi tên */ }
  if (!items.length) runs.push({ role, reason: 'không có kết quả thẩm định', session: '' });
  for (const item of items) {
    const p = item && item.json && typeof item.json === 'object' ? item.json : {};
    runs.push({ role, reason: turnProblem(p, role), session: oneLine(p.session, 80) });
    // Vẫn đọc phát hiện của lượt không hoàn tất: chỉ làm kết quả chặt hơn, không lỏng hơn.
    for (const line of String(p.text || '').split('\n')) {
      const m = RE.exec(line);
      if (!m) continue;
      const sev = m[1].toUpperCase();
      const loc = m[2] || '';
      if ((sev === 'BLOCKER' || sev === 'CRITICAL') && !loc) continue;
      const key = `${loc}|${m[3].slice(0, 60).toLowerCase()}`;
      const prev = byKey.get(key);
      if (prev) { prev.roles.add(role); if (RANK[sev] > RANK[prev.severity]) prev.severity = sev; }
      else byKey.set(key, { severity: sev, location: loc, detail: m[3].trim(), roles: new Set([role]) });
    }
  }
}

const total = REVIEWS.length;
const failed = runs.filter((r) => r.reason);
const failedRoles = [...new Set(failed.map((r) => r.role))];
// "Đồng thuận" = số VAI TRÒ khác nhau cùng nêu một vấn đề, không phải số dòng trùng.
const findings = [...byKey.values()]
  .map((f) => ({ severity: f.severity, location: f.location, detail: f.detail, votes: f.roles.size, roles: [...f.roles] }))
  .sort((a, b) => RANK[b.severity] - RANK[a.severity] || b.votes - a.votes);
const blockers = findings.filter((f) => f.severity === 'BLOCKER' || f.severity === 'CRITICAL');
const state = blockers.length ? 'failure' : failed.length ? 'error' : 'success';

const parts = [];
if (blockers.length || !failed.length) parts.push(`${blockers.length} mục chặn`);
parts.push(failed.length
  ? `Thẩm định KHÔNG hoàn tất (${failedRoles.length}/${total}): ${failed.map((r) => `${r.role}: ${r.reason}`).join('; ')}`
  : `${total}/${total} lượt thẩm định hoàn tất`);
// GitHub trả 422 nếu description dài quá 140 ký tự.
const chars = [...parts.join(' · ')];
const description = chars.length > 140 ? `${chars.slice(0, 139).join('')}…` : chars.join('');

const lines = ['## Thẩm định tự động của Agent Fleet', ''];
if (failed.length) {
  lines.push(
    `**Thẩm định KHÔNG hoàn tất: ${failedRoles.length}/${total} vai trò không cho kết quả dùng được.** ` +
      'Lượt hỏng cũng cho ra 0 phát hiện, nên kết quả này KHÔNG phải một lần thẩm định sạch.',
    '',
    '| Vai trò | Lý do | Phiên |', '|---|---|---|',
    ...failed.map((r) => `| ${r.role} | ${cell(r.reason, 200)} | ${r.session ? `\`${cell(r.session, 80).replace(/`/g, '')}\`` : '—'} |`),
    '',
  );
}
lines.push(
  blockers.length ? `**${blockers.length} mục chặn merge.**`
    : failed.length ? '**Không thấy mục chặn trong các lượt đã chạy — chưa đủ để kết luận.**'
    : '**Không có mục chặn merge.**',
  '',
);
if (findings.length) {
  lines.push(
    '| Mức | Vị trí | Vấn đề | Đồng thuận |', '|---|---|---|---|',
    ...findings.slice(0, 40).map((f) => `| ${f.severity} | \`${f.location || '—'}\` | ${cell(f.detail, 200)} | ${f.votes}/${total} |`),
    '',
  );
}
lines.push(
  `_${total} lượt thẩm định độc lập (${REVIEWS.map((r) => r.role).join(', ')}) cùng soi diff này. ` +
    'Cột “đồng thuận” cho biết bao nhiêu lượt cùng nêu một vấn đề. Một lượt chỉ được tính khi thoát mã 0 ' +
    'và kết thúc bằng khối `fleet-status` có outcome success hoặc partial._',
);

return [{
  json: {
    state, description, blockerCount: blockers.length, incompleteRoles: failedRoles,
    reviews: runs, findings, body: lines.join('\n'),
  },
  // Item này suy ra từ mọi item đầu vào (cả ba lượt thẩm định).
  pairedItem: $input.all().map((_, i) => ({ item: i })),
}];
